    <div className="toolbar"><div className="search"><Search/><Input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar marca, tipo ou cor"/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Todos</option><option value="low">Estoque baixo</option><option value="active">Ativos</option><option value="archived">Arquivados</option></select><Badge variant="outline">{items.length} materiais</Badge></div>
